<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { fetchSeoContentAssets,fetchSeoKeywords } from '../../api/seo'
import { fetchSeoSites } from '../../api/moduleAssets'
import { currentTenantId,session } from '../../store/session'
import { currentSeoSiteId as siteId } from './seoSiteContext'

const router=useRouter(),loading=ref(false),error=ref(''),assets=ref([]),keywords=ref([]),query=ref(''),tab=ref('all'),sourceVisible=ref(false),sourceMode=ref('library'),selectedSourceId=ref(null),sourceText=ref(''),sourceOrigin=ref('原创文章列表'),rewriteStrength=ref('深度改写（推荐）'),targetKeywords=ref('')
const sites=ref([])
const canEdit=computed(()=>!session.isLoggedIn||session.canEdit('seo.content'))
const rewrites=computed(()=>assets.value.filter(item=>item.content_type==='rewrite'))
const originalArticles=computed(()=>assets.value.filter(item=>['article','guide','landing','comparison','faq'].includes(item.content_type)&&(item.humanized_content||item.draft)))
const selectedSource=computed(()=>originalArticles.value.find(item=>item.id===selectedSourceId.value)||null)
const keywordMap=computed(()=>new Map(keywords.value.map(item=>[item.id,item])))
const thisMonth=computed(()=>{const now=new Date();return rewrites.value.filter(item=>{const d=new Date(item.updated_at);return d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth()&&['review','published'].includes(item.status)}).length})
const scored=computed(()=>rewrites.value.filter(item=>item.originality_score!=null))
const averageOriginality=computed(()=>scored.value.length?Math.round(scored.value.reduce((sum,item)=>sum+item.originality_score,0)/scored.value.length):null)
const tabs=computed(()=>[
  {key:'all',label:'全部',count:rewrites.value.length},
  {key:'planned',label:'待改写',count:rewrites.value.filter(i=>i.status==='planned').length},
  {key:'drafting',label:'改写中',count:rewrites.value.filter(i=>i.status==='drafting').length},
  {key:'review',label:'待发布',count:rewrites.value.filter(i=>i.status==='review').length},
  {key:'published',label:'已发布',count:rewrites.value.filter(i=>i.status==='published').length},
])
const rows=computed(()=>{const needle=query.value.trim().toLowerCase();return rewrites.value.filter(item=>(tab.value==='all'||item.status===tab.value)&&(!needle||item.title.toLowerCase().includes(needle)||(item.source_text||'').toLowerCase().includes(needle)||(keywordMap.value.get(item.keyword_id)?.keyword||'').toLowerCase().includes(needle)))})
const statusLabel=value=>({planned:'待改写',drafting:'改写中',review:'待发布',published:'已发布',archived:'已归档'})[value]||value
const statusClass=value=>({planned:'gray',drafting:'amber',review:'blue',published:'green'})[value]||'gray'
const date=value=>value?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'
const plain=value=>String(value||'').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim()
const sourceTitle=item=>{const text=plain(item.source_text);return text?`原文：${text.slice(0,30)}${text.length>30?'…':''}`:`改写稿：${item.title}`}
const sourceMeta=item=>item.source_text?`已导入原文 · ${plain(item.source_text).length.toLocaleString()} 字`:`尚未保存原文 · ${plain(item.draft).length.toLocaleString()} 字`
const targetPlatforms=item=>{if(item.target_platforms?.length)return item.target_platforms;if(!item.page_url)return[];try{return[new URL(item.page_url).hostname]}catch{return[item.page_url]}}
const actionLabel=item=>item.status==='planned'?'开始改写':item.status==='drafting'?'继续编辑':item.status==='review'?'检查并发布':item.status==='published'?'查看版本':'查看'
async function load(){if(!currentTenantId.value){error.value='请先选择客户';assets.value=[];return}if(!siteId.value){error.value='请先选择或创建 SEO 网站';assets.value=[];return}loading.value=true;try{const [content,words]=await Promise.all([fetchSeoContentAssets({tenantId:currentTenantId.value,siteId:siteId.value}),fetchSeoKeywords({tenantId:currentTenantId.value,siteId:siteId.value,status:'',pageSize:200})]);assets.value=content.items;keywords.value=words.items;error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadSites(){if(!currentTenantId.value){sites.value=[];siteId.value=null;return load()}try{sites.value=(await fetchSeoSites(currentTenantId.value)).sites||[];const selected=sites.value.some(item=>item.id===siteId.value)?siteId.value:(sites.value.find(item=>item.status==='active')?.id||sites.value[0]?.id||null);if(selected!==siteId.value)siteId.value=selected;else await load()}catch(e){error.value=e.message}}
function sourceContent(item){return String(item?.humanized_content||item?.draft||'').replace(/<br\s*\/?>/gi,'\n').replace(/<\/p>/gi,'\n\n').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').trim()}
function importSource(){sourceMode.value=originalArticles.value.length?'library':'paste';selectedSourceId.value=null;sourceText.value='';sourceOrigin.value=sourceMode.value==='library'?'原创文章列表':'直接粘贴';rewriteStrength.value='深度改写（推荐）';targetKeywords.value='';sourceVisible.value=true}
function chooseSource(item){selectedSourceId.value=item.id;sourceText.value=sourceContent(item);sourceOrigin.value='原创文章列表';targetKeywords.value=keywordMap.value.get(item.keyword_id)?.keyword||''}
function startRewrite(){
  const source=sourceText.value.trim()
  if(sourceMode.value==='library'&&!selectedSource.value)return ElMessage.warning('请选择一篇原创文章')
  if(!source)return ElMessage.warning('请粘贴待改写原文')
  const sourceTitle=selectedSource.value?.title||'粘贴原文'
  sessionStorage.setItem('seo_pending_rewrite_source',source)
  sessionStorage.setItem('seo_pending_rewrite_options',JSON.stringify({sourceOrigin:sourceOrigin.value,sourceAssetId:selectedSource.value?.id||null,sourceTitle,keywordId:selectedSource.value?.keyword_id||null,rewriteStrength:rewriteStrength.value,targetKeywords:targetKeywords.value,autoGenerate:true}))
  sourceVisible.value=false
  router.push({path:'/seo/content/editor',query:{type:'rewrite',new:'1',autogenerate:'1',site_id:siteId.value}})
}
function edit(item){router.push({path:'/seo/content/editor',query:{type:'rewrite',id:item.id,site_id:item.site_id||siteId.value}})}
watch(siteId,load);watch(currentTenantId,loadSites);onMounted(loadSites)
</script>

<template>
  <div class="seo-content-page" v-loading="loading">
    <header class="topbar">
      <div><h1>文章改写</h1><div class="sub">基于客户已有内容智能改写，扩大关键词覆盖与全网声量</div></div>
      <div class="right"><el-select v-model="siteId" class="rewrite-site-picker" placeholder="选择 SEO 网站"><el-option v-for="site in sites" :key="site.id" :label="site.name||site.canonical_domain" :value="site.id" /></el-select><button v-if="canEdit" class="btn" @click="importSource">导入原文</button><button v-if="canEdit" class="btn primary" @click="importSource">AI 智能改写</button><div class="avatar">{{String(session.user?.name||session.user?.username||'DZ').slice(0,2).toUpperCase()}}</div></div>
    </header>
    <main class="content">
      <section class="article-intro rewrite">
        <div class="intro-copy"><span class="intro-kicker">Rewrite Content</span><h2>文章改写不是简单换词，而是保留事实、重构表达并植入目标关键词</h2><p>导入官网旧文或客户提供的参考稿，AI 按目标搜索引擎重写标题、结构和段落；系统同时检查相似度、关键词次数与事实一致性。</p><div class="intro-rules"><span>保留核心事实</span><span>结构重组</span><span>关键词显式统计</span><span>批量铺量</span></div></div>
        <div class="intro-flow" aria-label="文章改写工作流"><div v-for="(item,index) in [['导入','原创文章或直接粘贴'],['直接选择','确定原文与改写强度'],['AI 生成','事实锁定、表达重构'],['发布','登记地址与目标平台']]" :key="item[0]" class="intro-step"><span class="step-no">{{index+1}}</span><b>{{item[0]}}</b><small>{{item[1]}}</small></div></div>
      </section>
      <section class="article-metrics" aria-label="文章改写数据概览"><div class="article-metric"><span>可改写原文</span><strong>{{originalArticles.length}}</strong><em>来自原创文章列表</em></div><div class="article-metric"><span>本月已改写</span><strong>{{thisMonth}}</strong><em>进入审核或已发布</em></div><div class="article-metric"><span>目标词植入</span><strong>{{rewrites.filter(i=>i.keyword_id).length}}</strong><em>已绑定目标关键词</em></div><div class="article-metric"><span>平均原创度</span><strong>{{averageOriginality==null?'—':`${averageOriginality}%`}}</strong><em>{{scored.length?'基于已检测任务':'尚无检测结果'}}</em></div></section>
      <section class="article-workbench">
        <div class="workbench-bar"><h3>改写任务</h3><button v-for="item in tabs" :key="item.key" class="filter-chip" :class="{active:tab===item.key}" @click="tab=item.key">{{item.label}} {{item.count}}</button><input v-model="query" class="search" placeholder="搜索原文、改写稿或关键词"></div>
        <div class="table-wrap"><table class="article-list-table"><thead><tr><th>原文 / 改写任务</th><th>植入关键词</th><th>改写质量</th><th>状态</th><th>目标平台</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td class="article-title-cell"><strong>{{sourceTitle(item)}}</strong><small>{{sourceMeta(item)}}</small></td><td><div class="keyword-stack"><span v-if="item.keyword_id">{{keywordMap.get(item.keyword_id)?.keyword||'目标关键词'}}</span><span v-else>待绑定</span></div></td><td><span v-if="item.originality_score!=null" class="quality-score"><i :style="{'--score':`${item.originality_score}%`}"/>原创度 {{item.originality_score}}%</span><span v-else-if="item.rewrite_progress!=null" class="quality-score"><i :style="{'--score':`${item.rewrite_progress}%`}"/>{{item.rewrite_progress}}</span><span v-else class="quality-score"><i style="--score:0%"/>待生成</span></td><td><span class="badge" :class="statusClass(item.status)">{{statusLabel(item.status)}}</span></td><td><div class="platform-pills"><span v-for="platform in targetPlatforms(item)" :key="platform" :class="{live:item.status==='published'}">{{platform}}</span><span v-if="!targetPlatforms(item).length">未选择</span></div></td><td>{{date(item.updated_at)}}</td><td><div class="table-actions"><button class="text-action" @click="edit(item)">{{actionLabel(item)}}</button></div></td></tr><tr v-if="!rows.length"><td colspan="7"><div class="empty-state"><b>{{error||'暂无改写任务'}}</b><span>导入原文后创建第一条真实改写任务</span><button v-if="canEdit" class="btn primary" @click="importSource">导入原文</button></div></td></tr></tbody></table></div>
      </section>
    </main>
    <div v-if="sourceVisible" class="source-overlay" @click.self="sourceVisible=false"><section><header><div><h3>导入待改写原文</h3><p>从原创文章列表直接选择，或粘贴一篇新的原文</p></div><button @click="sourceVisible=false">×</button></header><main>
      <div class="source-mode full"><button :class="{active:sourceMode==='library'}" type="button" @click="sourceMode='library';sourceOrigin='原创文章列表'">原创文章列表</button><button :class="{active:sourceMode==='paste'}" type="button" @click="sourceMode='paste';selectedSourceId=null;sourceText='';sourceOrigin='直接粘贴'">直接粘贴</button></div>
      <div v-if="sourceMode==='library'" class="source-library full"><button v-for="item in originalArticles" :key="item.id" :class="{selected:selectedSourceId===item.id}" type="button" @click="chooseSource(item)"><span><strong>{{item.title}}</strong><small>{{sourceContent(item).length.toLocaleString()}} 字 · {{statusLabel(item.status)}}</small></span><i>{{selectedSourceId===item.id?'已选择':'选择'}}</i></button><div v-if="!originalArticles.length" class="source-library-empty">暂无可用原创文章，请切换到“直接粘贴”。</div></div>
      <label v-else class="full">原文内容 *<textarea v-model="sourceText" placeholder="粘贴客户已有文章或参考文章…"/></label>
      <label>改写强度<select v-model="rewriteStrength"><option>深度改写（推荐）</option><option>中度改写</option><option>轻度润色</option></select></label><label>目标关键词<input v-model="targetKeywords" placeholder="多个关键词用逗号分隔"></label>
      <label v-if="sourceMode==='library'" class="full">已选原文预览<textarea :value="sourceText" readonly placeholder="选择原创文章后显示原文"/></label>
    </main><footer><button @click="sourceVisible=false">取消</button><button class="primary" @click="startRewrite">导入并生成改写</button></footer></section></div>
  </div>
</template>

<style scoped>
.rewrite-site-picker{width:210px}
.seo-content-page{min-height:100vh;background:#f4f6f9;color:#1e2330;font:14px/1.5 -apple-system,"PingFang SC","Microsoft YaHei","Segoe UI",Roboto,sans-serif}.topbar{min-height:68px;display:flex;align-items:center;gap:16px;padding:0 28px;border-bottom:1px solid #e8eaf0;background:#fff}.topbar h1{margin:0;font-size:17px}.topbar .sub{color:#6b7280;font-size:12px}.topbar .right{margin-left:auto;display:flex;align-items:center;gap:12px}.btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border:1px solid #e8eaf0;border-radius:9px;background:#fff;color:#1e2330;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.btn.primary{border-color:#2563eb;background:#2563eb;color:#fff}.avatar{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:#2563eb;color:#fff;font-size:12px;font-weight:700}.content{padding:20px 24px 28px}.article-intro{min-height:138px;margin-bottom:16px;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(420px,1fr);overflow:hidden;border-radius:8px;background:#29302f;color:#fff;box-shadow:0 12px 30px rgba(28,37,54,.13)}.intro-copy{padding:24px 26px;border-right:1px solid rgba(255,255,255,.1)}.intro-kicker{display:inline-flex;align-items:center;gap:7px;color:#b8d9bd;font-size:11px;font-weight:750;letter-spacing:.08em;text-transform:uppercase}.intro-copy h2{margin:8px 0 6px;font-size:21px;letter-spacing:0}.intro-copy p{max-width:720px;margin:0;color:#b9c1cf;font-size:13px}.intro-rules{display:flex;flex-wrap:wrap;gap:7px;margin-top:15px}.intro-rules span{padding:4px 8px;border:1px solid rgba(255,255,255,.12);border-radius:5px;background:rgba(255,255,255,.05);color:#d8deea;font-size:11px}.intro-flow{display:grid;grid-template-columns:repeat(4,1fr);align-items:center;padding:20px 20px 20px 12px}.intro-step{position:relative;min-width:0;padding:8px 9px}.intro-step:not(:last-child)::after{position:absolute;top:22px;right:-3px;width:12px;height:1px;background:rgba(255,255,255,.25);content:""}.intro-step b{display:block;margin-bottom:5px;color:#fff;font-size:12px}.intro-step small{display:block;color:#aab3c2;font-size:10.5px;line-height:1.45}.step-no{width:24px;height:24px;margin-bottom:8px;display:grid;place-items:center;border-radius:50%;background:#b8d9bd;color:#1d2c21;font-size:11px;font-weight:800}.article-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}.article-metric{min-height:92px;padding:14px 16px;border:1px solid #e0e3e9;border-radius:8px;background:#fff}.article-metric span{display:block;color:#7a8290;font-size:11px}.article-metric strong{display:inline-block;margin:5px 6px 0 0;color:#182033;font-size:23px;line-height:1}.article-metric em{color:#16a34a;font-size:11px;font-style:normal;font-weight:650}.article-workbench{overflow:hidden;border:1px solid #dfe3ea;border-radius:8px;background:#fff}.workbench-bar{min-height:58px;padding:10px 14px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #e5e7eb}.workbench-bar h3{margin:0 10px 0 0;font-size:14px}.filter-chip{padding:6px 10px;border:1px solid #e0e4eb;border-radius:6px;background:#fff;color:#697180;font-size:11px;cursor:pointer}.filter-chip.active{border-color:#9bb9f6;background:#f0f5ff;color:#1d4ed8;font-weight:700}.search{width:230px;margin-left:auto;padding:8px 12px;border:1px solid #e8eaf0;border-radius:9px;background:#f6f7fb;color:#1e2330;font-size:13px}.table-wrap{overflow:auto}.article-list-table{width:100%;border-collapse:collapse;font-size:13px}.article-list-table th,.article-list-table td{padding:12px 14px;border-bottom:1px solid #e8eaf0;text-align:left;vertical-align:middle}.article-list-table th{color:#6b7280;font-size:12px;font-weight:600}.article-table tbody tr:last-child td{border-bottom:0}.article-title-cell{min-width:320px}.article-title-cell strong{display:block;max-width:520px;margin-bottom:4px;color:#222938;font-size:13px}.article-title-cell small{color:#8a919e;font-size:11px}.keyword-stack{display:flex;max-width:230px;flex-wrap:wrap;gap:5px}.keyword-stack span,.platform-pills span{padding:3px 7px;border-radius:5px;background:#f0f2f6;color:#626c7b;font-size:10.5px}.platform-pills{display:flex;max-width:200px;flex-wrap:wrap;gap:5px}.platform-pills .live{background:#e9f7ef;color:#137f4a}.table-actions{display:flex;align-items:center;gap:6px;white-space:nowrap}.text-action{padding:5px 7px;border:0;background:transparent;color:#2563eb;font-size:11.5px;font-weight:700;cursor:pointer}.text-action:hover{background:#eff4ff}.quality-score{display:inline-flex;align-items:center;gap:6px;color:#5e6675;font-size:11px}.quality-score i{width:48px;height:5px;overflow:hidden;border-radius:4px;background:#e9ecf1}.quality-score i::after{display:block;width:var(--score,70%);height:100%;background:#16a34a;content:""}.badge{display:inline-flex;padding:3px 9px;border-radius:999px;font-size:12px;font-weight:600}.badge.green{background:#e7f7ee;color:#16a34a}.badge.amber{background:#fdf2e0;color:#d97706}.badge.blue{background:#eff4ff;color:#2563eb}.badge.gray{background:#f0f1f5;color:#6b7280}.empty-state{height:190px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;color:#8d96a4}.source-overlay{position:fixed;inset:0;z-index:100;display:grid;place-items:center;background:rgba(20,27,39,.45)}.source-overlay>section{width:min(760px,calc(100vw - 32px));max-height:90vh;display:flex;overflow:hidden;flex-direction:column;border-radius:12px;background:#fff;box-shadow:0 28px 70px rgba(20,27,39,.25)}.source-overlay header,.source-overlay footer{padding:18px 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e8ebf0}.source-overlay header h3{margin:0}.source-overlay header p{margin:4px 0 0;color:#7b8493;font-size:11px}.source-overlay button{height:38px;padding:0 17px;border:1px solid #dfe3e9;border-radius:9px;background:#fff;color:#283143;font-size:12px;font-weight:700;cursor:pointer}.source-overlay header>button{padding:0;border:0;font-size:20px}.source-overlay main{padding:22px;display:grid;grid-template-columns:1fr 1fr;gap:15px;overflow:auto}.source-overlay label{display:grid;gap:8px;font-size:12px;font-weight:700}.source-overlay .full{grid-column:1/-1}.source-overlay textarea,.source-overlay input,.source-overlay select{width:100%;padding:10px 12px;border:1px solid #dfe3e9;border-radius:8px;background:#fff;outline:0;font:inherit}.source-overlay textarea{min-height:130px;resize:vertical;line-height:1.7}.source-overlay footer{justify-content:flex-end;gap:10px;border-top:1px solid #e8ebf0;border-bottom:0}.source-overlay .primary{border-color:#2563eb;background:#2563eb;color:#fff}.source-mode{display:flex;gap:8px}.source-mode button{flex:1}.source-mode button.active{border-color:#2563eb;background:#eff4ff;color:#1d4ed8}.source-library{max-height:250px;display:grid;gap:8px;overflow:auto}.source-library>button{height:auto;min-height:58px;padding:10px 12px;display:flex;align-items:center;justify-content:space-between;text-align:left}.source-library>button.selected{border-color:#2563eb;background:#f5f8ff}.source-library span,.source-library strong,.source-library small{display:block}.source-library span{min-width:0}.source-library strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.source-library small{margin-top:4px;color:#7b8493;font-weight:400}.source-library i{color:#2563eb;font-size:11px;font-style:normal}.source-library-empty{padding:24px;border:1px dashed #d8dee8;border-radius:8px;color:#7b8493;text-align:center}@media(max-width:1180px){.article-intro{grid-template-columns:1fr}.intro-copy{border-right:0;border-bottom:1px solid rgba(255,255,255,.1)}}@media(max-width:1020px){.article-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.topbar{align-items:flex-start;flex-wrap:wrap;gap:10px;padding:12px 14px}.content{padding:14px}.article-metrics{grid-template-columns:1fr}.workbench-bar{align-items:flex-start;flex-wrap:wrap}.search{width:100%;margin-left:0}.source-overlay main{grid-template-columns:1fr}.source-overlay .full{grid-column:auto}}
